/** One list, rendered with its nested lists inside their parent item. */
function renderList(items, definitions) {
  function renderItems(itemList) {
    const lines = []
    for (const item of itemList) {
      if (item.children.length === 0) {
        lines.push(`<li>${renderInline(item.text, definitions)}</li>`)
      } else {
        lines.push(`<li>${renderInline(item.text, definitions)}`)
        lines.push('<ul>')
        lines.push(...renderItems(item.children))
        lines.push('</ul>')
        lines.push('</li>')
      }
    }
    return lines
  }

  const itemLines = renderItems(items)
  const allLines = ['<ul>', ...itemLines, '</ul>']
  return allLines.join('\n')
}

